import Foundation

/// One row of the seeded canonical ingredient library, decoded from
/// `Resources/seed_ingredients.json` (generated by `scripts/build_seed.py` from the
/// hand-authored, CC0 `scripts/seed_source.json` — spec §6). Keys are snake_case
/// like the workout seed (`Storage/ExerciseSeed.swift` @5bffddfb80fc).
///
/// `slug` is the stable key reseeding upserts on; it never changes, so a seed entry
/// can be re-described (category, aliases) without touching the user's rows or a
/// renamed `canonical_name`. `aliases` are stored normalized (§7.1) at seed time.
struct SeedIngredient: Codable, Equatable {
    var slug: String
    var canonicalName: String
    var category: IngredientCategory
    var aliases: [String]

    enum CodingKeys: String, CodingKey {
        case slug
        case canonicalName = "canonical_name"
        case category
        case aliases
    }
}

enum IngredientSeed {
    enum SeedError: Error { case missingResource }

    /// Shown in Settings as "Seed version". Kept in sync by hand with
    /// `SEED_VERSION` in `scripts/build_seed.py`.
    static let version = "2026.09"

    /// Loads the bundled seed library. Defaults to the main app bundle; tests pass
    /// their own bundle so they can seed without hosting into the app.
    static func load(from bundle: Bundle = .main) throws -> [SeedIngredient] {
        guard let url = bundle.url(forResource: "seed_ingredients", withExtension: "json") else {
            throw SeedError.missingResource
        }
        let data = try Data(contentsOf: url)
        return try JSONDecoder().decode([SeedIngredient].self, from: data)
    }
}
